window.products.push({"id":926978,"name":"TCL Energy Star 15,000 BTU 115V Window-Mounted Remote Control, TWC-15CR/UH Air Conditioner, White","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/71UDZ1uKiyL._AC_SL1500_.jpg","description":"Window air conditioners from TCL are the best way to beat the heat for anyone without a central cooling system. Whether you're looking to cool a small bedroom or an expansive living room, the TCL UH series has the ideal unit for you. For cooling a room up to 700 square feet, our 15, 000 BTU window air conditioner features on-board electronic controls with 3 speeds and a handy remote control. With our 24-hour on/off timer, cool strong airflow is at your command. Plus, setup is quick and easy with a long power cord and the included window mounting kit.","images":["https://m.media-amazon.com/images/I/71UDZ1uKiyL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"TCL","source_asin":"B07DGMBZN9","category_path":"Home & Kitchen"},"sku":"BM-926978","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B07DGMBZN9","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B07DGMBZN9","price_pending":true,"merchant_ready":false});
